function BorrowerPicker({borrowers,setBorrowers,value,onChange}:{borrowers:T.Borrower[];setBorrowers:React.Dispatch<React.SetStateAction<T.Borrower[]>>;value:string;onChange:(id:string)=>void}){const [newName,setNewName]=useState("");return <><Field label="Prestatario existente"><select value={value} onChange={e=>onChange(e.target.value)}><option value="">Seleccionar...</option>{borrowers.map(b=><option key={b.id} value={b.id}>{b.name} {b.phone?`· ${b.phone}`:""}</option>)}</select></Field><div className="notice"><b>¿Es una persona nueva?</b><div className="form2"><input value={newName} onChange={e=>setNewName(e.target.value)} placeholder="Nombre completo"/><Btn secondary onClick={()=>{if(!newName)return;const b={id:`b${Date.now()}`,name:newName};setBorrowers(p=>[...p,b]);onChange(b.id);setNewName("")}}>Crear prestatario</Btn></div><p>Así, si Carlos vuelve a pedir dinero dentro de un año, puedes reutilizar su mismo historial en lugar de crear otro Carlos.</p></div></>}

function LoanModal({borrowers,setBorrowers,accounts=[],data,close,save}:{borrowers:T.Borrower[];setBorrowers:React.Dispatch<React.SetStateAction<T.Borrower[]>>;accounts?:T.FinancialAccount[];data:any;close:()=>void;save:(x:T.Loan)=>void}){const [borrowerId,setBorrowerId]=useState(data?.borrowerId||""),[principal,setPrincipal]=useState(String(data?.principal||"2000")),[rate,setRate]=useState(String(data?data.rate*100:"10")),[frequency,setFrequency]=useState<T.Frequency>(data?.frequency||"Semanal"),[term,setTerm]=useState(String(data?.term||4)),[start,setStart]=useState(data?.startDate||today),[accountId,setAccountId]=useState(data?.accountId||"");const borrower=borrowers.find(b=>b.id===borrowerId);const plan=simpleLoanPlan(Number(principal||0),Number(rate||0)/100,Number(term||0));const next=addDays(start,frequency==="Semanal"?7:frequency==="Quincenal"?14:30);return <Modal title={data?"Editar préstamo":"Nuevo préstamo otorgado"} close={close} wide><AccountPicker accounts={accounts} value={accountId} onChange={setAccountId} required/><BorrowerPicker borrowers={borrowers} setBorrowers={setBorrowers} value={borrowerId} onChange={setBorrowerId}/><div className="form2"><Field label="Capital prestado"><input type="number" value={principal} onChange={e=>setPrincipal(e.target.value)}/></Field><Field label="Tasa total sobre capital %"><input type="number" value={rate} onChange={e=>setRate(e.target.value)}/></Field><Field label="Frecuencia"><select value={frequency} onChange={e=>setFrequency(e.target.value as T.Frequency)}>{frequencies.map(f=><option key={f}>{f}</option>)}</select></Field><Field label="Número de cuotas / periodos"><input type="number" min="1" value={term} onChange={e=>setTerm(e.target.value)}/></Field><Field label="Fecha de inicio"><input type="date" value={start} onChange={e=>setStart(e.target.value)}/></Field></div><div className="needmoney">Interés total <b>{money(plan.interest)}</b> · total a cobrar <b>{money(plan.total)}</b> · cuota <b>{money(plan.installment)}</b> · próximo pago <b>{next}</b></div><div className="notice"><b>Regla de Finanzas 360</b><p>En préstamos que tú otorgas, la tasa se aplica una sola vez al capital inicial. Ejemplo: S/ 2,000 + 10% = S/ 2,200; dividido entre 4 semanas = S/ 550 por semana.</p></div><div className="table"><div className="thead"><span>#</span><span>Cuota</span><span>Capital</span><span>Interés</span></div>{plan.installments.slice(0,8).map(x=><div className="tr" key={x.number}><span>{x.number}</span><span>{money(x.amount)}</span><span>{money(x.principal)}</span><span>{money(x.interest)}</span></div>)}</div><Btn onClick={()=>borrowerId&&save({id:data?.id||`l${Date.now()}`,borrowerId,borrower:borrower?.name||data?.borrower||"",principal:Number(principal),balance:data?.balance??Number(principal),rate:Number(rate)/100,frequency,term:Number(term),installment:plan.installment,totalScheduled:plan.total,recovered:data?.recovered||0,interestRecovered:data?.interestRecovered||0,nextPayment:data?.nextPayment||next,status:data?.status||"Al día",startDate:start,accountId:accountId||undefined})}>Guardar préstamo</Btn></Modal>}
function DebtModal({data,vehicles=[],accounts=[],close,save}:{data:any;vehicles?:T.Vehicle[];accounts?:T.FinancialAccount[];close:()=>void;save:(x:T.Debt)=>void}){const [lender,setLender]=useState(data?.lender||"BCP"),[product,setProduct]=useState(data?.product||"Préstamo personal"),[principal,setPrincipal]=useState(String(data?.principal||20000)),[tea,setTea]=useState(String(data?.tea||15)),[tcea,setTcea]=useState(String(data?.tcea||18)),[frequency,setFrequency]=useState<T.Frequency>(data?.frequency||"Mensual"),[term,setTerm]=useState(String(data?.term||24)),[desg,setDesg]=useState(String(data?.desgravamen||0.15)),[fees,setFees]=useState(String(data?.fees||0)),[vehicleId,setVehicleId]=useState(data?.vehicleId||""),[start,setStart]=useState(data?.startDate||today),[accountId,setAccountId]=useState(data?.accountId||"");const rate=Number(tea)/100,p=periodRate(rate,frequency),pay=paymentFor(Number(principal),p,Number(term));const final=addDays(start,(frequency==="Semanal"?7:frequency==="Quincenal"?14:30)*Number(term));return <Modal title={data?"Editar deuda":"Nueva deuda"} close={close} wide><div className="form2"><AccountPicker accounts={accounts} value={accountId} onChange={setAccountId} required/><Field label="Acreedor"><input value={lender} onChange={e=>setLender(e.target.value)}/></Field><Field label="Producto"><input value={product} onChange={e=>setProduct(e.target.value)}/></Field><Field label="Capital"><input type="number" value={principal} onChange={e=>setPrincipal(e.target.value)}/></Field><Field label="TEA %"><input type="number" value={tea} onChange={e=>setTea(e.target.value)}/></Field><Field label="TCEA % (si la conoces)"><input type="number" value={tcea} onChange={e=>setTcea(e.target.value)}/></Field><Field label="Frecuencia"><select value={frequency} onChange={e=>setFrequency(e.target.value as T.Frequency)}>{frequencies.map(f=><option key={f}>{f}</option>)}</select></Field><Field label="Número de cuotas"><input type="number" value={term} onChange={e=>setTerm(e.target.value)}/></Field><Field label="Desgravamen % mensual"><input type="number" value={desg} onChange={e=>setDesg(e.target.value)}/></Field><Field label="Comisiones / cargos"><input type="number" value={fees} onChange={e=>setFees(e.target.value)}/></Field><Field label="Vehículo relacionado"><select value={vehicleId} onChange={e=>setVehicleId(e.target.value)}><option value="">Sin vincular</option>{vehicles.map(v=><option key={v.id} value={v.id}>{v.brand} {v.model} · {v.plate}</option>)}</select></Field><Field label="Inicio"><input type="date" value={start} onChange={e=>setStart(e.target.value)}/></Field></div><div className="needmoney">Cuota calculada <b>{money(pay)}</b> · frecuencia <b>{frequency}</b> · plazo <b>{term} periodos</b> · fecha final estimada <b>{final}</b></div><div className="notice"><b>Si no tienes TCEA o desgravamen</b><p>Puedes dejarlos en 0 o como dato informativo. El sistema no inventará condiciones contractuales.</p></div><Btn onClick={()=>save({id:data?.id||`d${Date.now()}`,lender,product,principal:Number(principal),balance:data?.balance??Number(principal),annualRate:rate,tea:Number(tea),tcea:Number(tcea),installment:pay,frequency,term:Number(term),desgravamen:Number(desg),fees:Number(fees),vehicleId:vehicleId||undefined,nextPayment:data?.nextPayment||addDays(start,frequency==="Semanal"?7:frequency==="Quincenal"?14:30),startDate:start,finalDate:data?.finalDate||final,status:data?.status||"Activa",accountId:accountId||undefined})}>Guardar deuda</Btn></Modal>}

function LoanPaymentModal({loan,close,confirm}:{loan:T.Loan;close:()=>void;confirm:(loan:T.Loan,a:number)=>void}){const [amount,setAmount]=useState(String(loan.installment));return <Modal title={`Confirmar cobro · ${loan.borrower}`} close={close}><div className="notice"><b>Saldo actual: {money(loan.balance)}</b><p>Solo se aplicará cuando confirmes. Si fue un error, podrás revertirlo desde el historial.</p></div><Field label="Monto cobrado"><input type="number" value={amount} onChange={e=>setAmount(e.target.value)}/></Field><Btn onClick={()=>{confirm(loan,Number(amount));close()}}>Confirmar cobro</Btn></Modal>}

function DebtPaymentChooser({debts,data,close,confirm}:{debts:T.Debt[];data:any;close:()=>void;confirm:(d:T.Debt,a:number)=>void}){const [id,setId]=useState(data?.id||debts[0]?.id||"");const d=debts.find(x=>x.id===id)||debts[0];const [amount,setAmount]=useState(String(d?.installment||0));return <Modal title="Pagar deuda" close={close}><Field label="Selecciona la deuda"><select value={id} onChange={e=>{setId(e.target.value);const x=debts.find(d=>d.id===e.target.value);setAmount(String(x?.installment||0))}}>{debts.map(x=><option key={x.id} value={x.id}>{x.lender} · {x.product} · {money(x.balance)}</option>)}</select></Field><Field label="Monto"><input type="number" value={amount} onChange={e=>setAmount(e.target.value)}/></Field><div className="notice"><b>Confirmación antes de aplicar</b><p>Así evitas pagar accidentalmente otra deuda.</p></div><Btn onClick={()=>{if(d){confirm(d,Number(amount));close()}}}>Confirmar pago</Btn></Modal>}

function LoanDetail({loan,payments,close,reverse}:{loan:T.Loan;payments:T.LoanPayment[];close:()=>void;reverse:(p:T.LoanPayment)=>void}){const plan=simpleLoanPlan(loan.principal,loan.rate,loan.term);return <Modal title={`Detalle del préstamo · ${loan.borrower}`} close={close} wide><div className="grid3"><Detail label="Capital original" value={money(loan.principal)}/><Detail label="Saldo de capital" value={money(loan.balance)}/><Detail label="Cuota" value={money(loan.installment)}/></div><div className="notice"><b>Interés pactado</b><p>{money(plan.interest)} sobre el capital inicial · total programado {money(plan.total)} · interés cobrado {money(loan.interestRecovered||0)}.</p></div><CardBox title="Plan de cobro simple"><div className="table"><div className="thead"><span>Cuota</span><span>Pago</span><span>Capital</span><span>Interés</span></div>{plan.installments.slice(0,12).map(x=><div className="tr" key={x.number}><span>{x.number}</span><span>{money(x.amount)}</span><span>{money(x.principal)}</span><span>{money(x.interest)}</span></div>)}</div></CardBox><CardBox title="Pagos registrados">{payments.map(p=><div className="mini" key={p.id}><b>{p.date} · {money(p.amount)} {p.status==="Anulado"&&<Badge tone="danger">Anulado</Badge>}</b><small>Capital {money(p.principal)} · Interés {money(p.interest)} · Mora {money(p.lateFee)} {p.status==="Confirmado"&&<button className="link" onClick={()=>reverse(p)}>Revertir</button>}</small></div>)}</CardBox></Modal>}
function DebtDetail({debt,payments,close,reverse}:{debt:T.Debt;payments:T.DebtPayment[];close:()=>void;reverse:(p:T.DebtPayment)=>void}){const rate=periodRate(debt.annualRate,debt.frequency),schedule=scheduleFor(debt.balance,rate,Math.max(1,debt.term));return <Modal title={`Detalle de deuda · ${debt.lender}`} close={close} wide><div className="grid3"><Detail label="Saldo" value={money(debt.balance)}/><Detail label="Cuota" value={money(debt.installment)}/><Detail label="TCEA" value={`${debt.tcea}%`}/></div><CardBox title="Historial de pagos">{payments.map(p=><div className="mini" key={p.id}><b>{p.date} · {money(p.amount)} {p.status==="Anulado"&&<Badge tone="danger">Anulado</Badge>}</b><small>Capital {money(p.principal)} · Interés {money(p.interest)} · Seguro {money(p.insurance)} {p.status==="Confirmado"&&<button className="link" onClick={()=>reverse(p)}>Revertir</button>}</small></div>)}</CardBox><CardBox title="Cuotas pendientes"><div className="table"><div className="thead"><span>#</span><span>Cuota</span><span>Capital</span><span>Interés</span><span>Saldo</span></div>{schedule.slice(0,12).map(x=><div className="tr" key={x.n}><span>{x.n}</span><span>{money(x.payment)}</span><span>{money(x.principal)}</span><span>{money(x.interest)}</span><span>{money(x.balance)}</span></div>)}</div></CardBox></Modal>}

