function GoalModal({data,close,save}:{data:any;close:()=>void;save:(x:T.Goal)=>void}){const [name,setName]=useState(data?.name||""),[target,setTarget]=useState(String(data?.target||"")),[current,setCurrent]=useState(String(data?.current||0)),[deadline,setDeadline]=useState(data?.deadline||"2026-12-31"),[category,setCategory]=useState(data?.category||"Personal"),[frequency,setFrequency]=useState<T.Frequency>(data?.frequency||"Mensual");const submit=()=>{const t=Number(target),c=Number(current);if(!name.trim()||!Number.isFinite(t)||t<=0||c<0||(!data&&c>t)||(data&&t<c))return;save({id:data?.id||`g${Date.now()}`,name:name.trim(),target:t,current:data?data.current:c,deadline,category:category.trim()||"Personal",frequency})};return <Modal title={data?"Editar meta":"Nueva meta"} close={close}><p className="modalIntro">El saldo de la meta se modifica mediante aportes y retiros para conservar historial. Al editar una meta no se sobrescribe su saldo acumulado.</p><div className="form2"><Field label="Nombre"><input autoFocus value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Objetivo"><input type="number" min="0.01" value={target} onChange={e=>setTarget(e.target.value)}/></Field><Field label={data?"Acumulado actual":"Acumulado inicial"}><input type="number" min="0" value={current} onChange={e=>setCurrent(e.target.value)} disabled={Boolean(data)}/></Field><Field label="Fecha objetivo"><input type="date" value={deadline} onChange={e=>setDeadline(e.target.value)}/></Field><Field label="Categoría"><input value={category} onChange={e=>setCategory(e.target.value)}/></Field><Field label="Frecuencia de aporte"><select value={frequency} onChange={e=>setFrequency(e.target.value as T.Frequency)}>{frequencies.map(f=><option key={f}>{f}</option>)}</select></Field></div><div className="actions modalActions"><Btn secondary onClick={close}>Cancelar</Btn><Btn onClick={submit}>{data?"Guardar cambios":"Crear meta"}</Btn></div></Modal>}

