  const [type,setType]=useState<T.InvestmentMovement["type"]>("Aporte"),[amount,setAmount]=useState(""),[accountId,setAccountId]=useState(investment.accountId||""),[notes,setNotes]=useState("");
  const needsCash=type!=="Rendimiento"; const submit=()=>{const n=Number(amount);if(!Number.isFinite(n)||n<=0||((type!=="Rendimiento")&&!accountId))return;save({type,amount:n,accountId:accountId||undefined,notes:notes||undefined})};
